import {jest} from '@jest/globals';
import {WebSocket} from 'ws';
import {createMessageHandler} from './ws/messageHandler.js';
import type {ChatOrchestrator} from '../orchestration/chatOrchestrator.js';
import type {ChatSession} from '../types/session.js';
import type {SessionStore} from '../types/sessionStore.js';
import {InMemorySessionStore} from '../infrastructure/stores/inMemorySessionStore.js';

describe('session list message handling', () => {
  it('answers with the authenticated user’s summaries and ISO dates', async () => {
    const inner = new InMemorySessionStore();
    const summary = {
      sessionId: 's2',
      createdAt: new Date('2026-01-01T00:00:00.000Z'),
      updatedAt: new Date('2026-01-02T00:00:00.000Z'),
      entryCount: 2,
    };
    let listedUserId: string | undefined;
    const listFor = jest.fn((userId: string) => {
      listedUserId = userId;
      return [summary];
    });
    const sessionStore = {...inner, listFor} as unknown as SessionStore;
    const sent: unknown[] = [];
    const ws = {send: (raw: string) => sent.push(JSON.parse(raw))} as unknown as WebSocket;
    const session: ChatSession = {sessionId: 's1', userId: 'u1', entries: []};
    const handle = createMessageHandler({} as ChatOrchestrator, sessionStore);

    await handle(ws, session, {type: 'list_sessions', limit: 5, userId: 'u2'});

    expect({userId: listedUserId, sent}).toEqual({
      userId: 'u1',
      sent: [
        {
          type: 'session_list',
          sessions: [
            {
              sessionId: 's2',
              createdAt: '2026-01-01T00:00:00.000Z',
              updatedAt: '2026-01-02T00:00:00.000Z',
              entryCount: 2,
            },
          ],
        },
      ],
    });
  });
});
Any other field is ignored, and the validator forwards only the fields the frame defines. In particular the server does not read a `chatId` from this message: the connection already determines the session ([validated by: drops any field the frame does not define, rather than forwarding it](../../src/transport/ws/validation.test.ts#L18)).

Constraints:

- `content` MUST NOT be empty or whitespace-only after trimming.
- `content` MUST NOT exceed 10,000 characters.
- Violation of these constraints results in an `error` response with code `INVALID_MESSAGE`.

One at a time:

- A session processes one `user_message` at a time, in the order the frames arrived: a frame arriving while an earlier one is still running waits, and its answer starts only after the earlier run's `stream_end` ([validated by: answers a second user_message only after the first has sent its stream_end, in the order they arrived](../../src/transport/ws/messageHandler.test.ts#L646)).
- The waiting message's model request therefore holds the earlier answer finished, never one still streaming ([validated by: hands the second run a history whose first answer is finished, never one still streaming](../../src/transport/ws/messageHandler.test.ts#L677)).
- A `ping` is answered at once, even while a run is pending ([validated by: answers a ping at once while a run is pending](../../src/transport/ws/messageHandler.test.ts#L695)).
- A frame that fails validation and is not a `user_message`, such as a malformed `ping`, gets its `INVALID_MESSAGE` at once, even while a run is pending, but a `user_message` that fails validation is answered in turn, its `INVALID_MESSAGE` and `stream_end` after the run in progress, since an `error` frame names no message and would otherwise read as the running answer's ([validated by: answers an invalid ping at once but an invalid user_message in turn, after the run in progress](../../src/transport/ws/messageHandler.test.ts#L708)).
- The reconnect flush (§ 11.3), which sends queued messages in one burst, is therefore safe: they are answered one after another, in the order the user typed them ([validated by: queues three messages sent in one tick before the handler returns, and answers them in that order](../../src/transport/ws/messageHandler.test.ts#L724)).
- A queued message whose socket has closed by the time its turn comes is dropped, neither recorded nor answered, since nobody is left to read the answer and a session whose last socket closed has no credentials left ([validated by: drops a queued message whose socket closed before its turn, without asking the model or recording it](../../src/transport/ws/messageHandler.test.ts#L741)).

### 4.2 ping

Application-level heartbeat. The server MUST respond with a `pong` message echoing the timestamp.

```json
{
  "type": "ping",
  "timestamp": 1705312200000
}
```

| Field       | Type   | Required | Description                       |
| ----------- | ------ | -------- | --------------------------------- |
| `type`      | string | Yes      | `"ping"`                          |
| `timestamp` | number | Yes      | Client timestamp in milliseconds  |

### 4.3 list_sessions

The validator accepts a bare `{type: 'list_conversations'}` frame ([validated by: accepts a bare list_conversations frame](../../src/transport/ws/validation.test.ts#L28)).

Requests the authenticated user's conversation summaries. The user identity comes from the WebSocket connection; a client-supplied `userId` is ignored. This request does not start a turn and is answered independently of the per-session message queue ([validated by: answers list_sessions for the authenticated user with ISO dates, forwarding limit and before while ignoring any client userId](../../src/transport/conversationList.acceptance.test.ts#L76)).

```json
{
  "type": "list_sessions",
  "limit": 20,
  "before": {"sessionId": "session-123", "updatedAt": "2026-10-27T12:00:00.000Z"}
}
```

| Field      | Type   | Required | Description                                                     |
| ---------- | ------ | -------- | --------------------------------------------------------------- |
| `type`     | string | Yes      | `"list_sessions"`                                               |
| `limit`    | number | No       | Maximum number of summaries to return; a non-negative integer  |
| `before`   | object | No       | Cursor containing `sessionId` and `updatedAt` for the next page |

The server uses the authenticated connection's `userId` when reading the store and returns summaries newest first. `createdAt` and `updatedAt` are ISO-8601 strings on the wire. A bare request is valid; malformed limits or cursors receive `INVALID_MESSAGE` ([validated by: accepts a bare list_sessions frame and rejects a malformed limit or before with INVALID_MESSAGE without calling listFor](../../src/transport/conversationList.acceptance.test.ts#L146)).

## 5. Server-to-Client Messages

### 5.1 connected

Sent exactly once after a successful handshake. See Section 2.3.

| Field            | Type     | Description                                            |
| ---------------- | -------- | ------------------------------------------------------ |
| `type`           | string   | `"connected"`                                          |
| `sessionId`      | string   | UUID v4 identifying the session                        |
| `message`        | string   | Human-readable greeting                                |
| `examplePrompts` | string[] | Example queries derived from registered tool definitions |
| `resumed`        | boolean  | Present only with resume enabled: whether the requested conversation was rejoined |
| `entryCount`     | number   | Present only when `resumed` is `true`: how many stored entries the replay covers, skipped ones included |
| `resumeFailure`  | string   | Present only when the connection named an id and `resumed` is `false`: `expired` when the caller's own session aged out, `unknown` otherwise. `unknown` deliberately covers both an id the server never issued and one that is not the caller's, so the answer reveals nothing about ids that exist |

### 5.2 entry_upsert

Creates a new entry or replaces an existing entry at the given index. This is the primary mechanism for adding content to the conversation.

```json
{
  "type": "entry_upsert",
  "index": 0,
  "entry": {
    "role": "user",
    "content": "What is the weather in Berlin?",
    "timestamp": "2026-01-15T14:30:00Z"
  }
}
```

| Field   | Type         | Description                            |
| ------- | ------------ | -------------------------------------- |
| `type`  | string       | `"entry_upsert"`                       |
| `index` | number       | Zero-based position in the entry array |
- `MongoSessionStore` reads such a cursor as a date before it queries, since a string compares against no stored BSON date and would quietly match none of them ([validated by: pages on a cursor that has been through JSON, where a string would have matched no stored date](../../src/infrastructure/stores/mongo/mongoConversationList.test.ts#L150)).
- A cursor carrying no usable moment is refused with an error naming it, rather than read as no cursor at all, which would answer the first page again and repeat rows a client has already shown ([validated by: pages on a cursor that has been through JSON, and refuses one carrying no usable moment](../../src/infrastructure/stores/inMemoryConversationList.test.ts#L123)).

## A collection that cannot list

- `find` is optional on `CollectionLike`, so an adapter written before conversation lists existed still satisfies the port ([validated by: refuses to list on a collection that implements no find, rather than reporting no conversations](../../src/infrastructure/stores/mongo/mongoConversationList.test.ts#L175)).
- A store built on a collection without it refuses to list, rather than reporting that the user has no conversations ([validated by: refuses to list on a collection that implements no find, rather than reporting no conversations](../../src/infrastructure/stores/mongo/mongoConversationList.test.ts#L175)).

## When the store cannot answer

- A store whose collection fails rejects rather than answering a partial or empty list: what to show a user who may have conversations is the caller's decision, and an empty history is not a safe guess ([validated by: rejects rather than answering a partial list when the collection fails](../../src/infrastructure/stores/mongo/mongoConversationList.test.ts#L225)).

## Over the WebSocket protocol

- The validator accepts a bare `{type: 'list_sessions'}` frame ([validated by: accepts a bare list_sessions frame](../../src/transport/ws/validation.test.ts#L24)).
- The handler calls `listFor` with the authenticated session's `userId`, ignores a client-supplied `userId`, and serialises summary dates as ISO strings ([validated by: answers with the authenticated user’s summaries and ISO dates](../../src/transport/sessionListHandler.test.ts#L10)).
- A client sends `{type: 'list_sessions', limit?, before?}` and receives `{type: 'session_list', sessions}` for the socket's authenticated user, with `createdAt` and `updatedAt` serialised as ISO-8601 strings and any client-supplied `userId` ignored ([validated by: answers list_sessions for the authenticated user with ISO dates, forwarding limit and before while ignoring any client userId](../../src/transport/conversationList.acceptance.test.ts#L76)).
- A store without `listFor` answers `{type: 'session_list', sessions: []}`, and a throwing `listFor` logs an error on the `ws` category and answers `{type: 'error', code: 'SERVER_ERROR'}` ([validated by: answers an empty session_list when the store has no listFor, and SERVER_ERROR with a ws error log when listFor throws](../../src/transport/conversationList.acceptance.test.ts#L117)).
- The validator accepts an optional integer `limit` from 1 through 200 and an optional `before` cursor whose `sessionId` is 1–128 characters and whose `updatedAt` parses as a valid timestamp, rejecting any other `list_sessions` payload with `INVALID_MESSAGE` without calling `listFor` ([validated by: accepts a bare list_sessions frame and rejects a malformed limit or before with INVALID_MESSAGE without calling listFor](../../src/transport/conversationList.acceptance.test.ts#L146), [validated by: accepts list_sessions limits from 1 through 200 and names the field when out of range](../../src/transport/ws/validation.test.ts#L28)).
