# Conversation List

| Field  | Value                 |
| ------ | --------------------- |
| Issue  | re-cinq/HALEngine#143 |
| Status | Shipped               |

Resume gets a client back into one conversation: the id it names, or the user's most recently active one. Neither tells it which conversations exist, and every other member of `SessionStore` answers about a session the caller can already name, so a consumer wanting to offer a conversation list had to query the collection behind the engine's back, against a document shape and a key the engine owns. `listFor` answers the list instead, as summaries rather than sessions. **GDPR.** A summary is personal data — that a user held a conversation, and when — so it carries no conversation content, it is filtered to one user by the query rather than in application code afterwards, and the retention bound stays the consumer's, through the store's `maxAgeMs` and erasure methods and re-cinq/HALEngine#41.

## The summary

- A summary is `sessionId`, `createdAt`, `updatedAt` and `entryCount`, and nothing else: neither the conversation's entries nor its credentials, so a list can never hand over either, even for a session created with credentials ([validated by: carries only its four fields, so a list can never hand over a conversation or a credential](../../src/infrastructure/stores/sessionStoreListSignature.test.ts#L22)).
import type {IncomingMessage} from '../../types/messages.js';

const MAX_CONTENT_LENGTH = 10000;

interface ValidationSuccess {
  valid: true;
  data: IncomingMessage;
}

interface ValidationFailure {
  valid: false;
  error: string;
}

export type ValidationResult = ValidationSuccess | ValidationFailure;

export function validateMessage(payload: unknown): ValidationResult {
  if (typeof payload !== 'object' || payload === null) {
    return {valid: false, error: 'Message must be an object'};
  }

  const message = payload as Record<string, unknown>;

  if (typeof message.type !== 'string') {
    return {valid: false, error: 'Message must have a type field'};
  }

  const validators: Record<string, (message: Record<string, unknown>) => ValidationResult> = {
    ['user_message']: validateUserMessage,
    ping: validatePingMessage,
    ['list_sessions']: validateListSessionsMessage,
    ['list_conversations']: validateListConversationsMessage,
  };
  const validate = validators[message.type];
  if (!validate) return {valid: false, error: `Unknown message type: ${message.type}`};
  return validate(message);
}

function validateListSessionsMessage(message: Record<string, unknown>): ValidationResult {
  return validateListMessage(message, 'list_sessions');
}

function validateListConversationsMessage(message: Record<string, unknown>): ValidationResult {
  return validateListMessage(message, 'list_conversations');
}

function validateListMessage(
  message: Record<string, unknown>,
  type: 'list_sessions' | 'list_conversations'
): ValidationResult {
  if (hasInvalidLimit(message.limit)) return {valid: false, error: `${type} limit must be an integer from 1 to 200`};

  if (type !== 'list_conversations') return validateSessionListMessage(message);

  const before = validateConversationCursor(message.before);
  if (!before.valid) return before;
  return {
    valid: true,
    data: {
      type,
      ...(message.limit === undefined ? {} : {limit: message.limit as number}),
      ...(before.before === undefined ? {} : {before: before.before}),
    },
  };
}

function validateSessionListMessage(message: Record<string, unknown>): ValidationResult {
  const validatedBefore = validateSessionCursor(message.before);
  if (!validatedBefore.valid) return validatedBefore;

  return {
    valid: true,
    data: {
      type: 'list_sessions',
      ...(message.limit === undefined ? {} : {limit: message.limit as number}),
      ...(validatedBefore.before === undefined ? {} : {before: validatedBefore.before}),
    },
  };
}

function validateConversationCursor(
  value: unknown
): {valid: true; before?: {sessionId: string; updatedAt: string}} | {valid: false; error: string} {
  if (value === undefined) return {valid: true};
  if (typeof value !== 'object' || value === null || Array.isArray(value)) {
    return {valid: false, error: 'list_conversations before must be a cursor object'};
  }

  const cursor = value as Record<string, unknown>;
  if (!isValidSessionId(cursor.sessionId)) {
    return {valid: false, error: 'list_conversations before.sessionId must be 1-128 characters'};
  }
  if (typeof cursor.updatedAt !== 'string' || !Number.isFinite(Date.parse(cursor.updatedAt))) {
    return {valid: false, error: 'list_conversations before.updatedAt must be a valid date string'};
  }
  return {valid: true, before: {sessionId: cursor.sessionId, updatedAt: cursor.updatedAt}};
}

function hasInvalidLimit(value: unknown): boolean {
  return value !== undefined && (typeof value !== 'number' || !Number.isInteger(value) || value < 1 || value > 200);
}

function validateSessionCursor(
  value: unknown
): {valid: true; before?: {sessionId: string; updatedAt: string | number}} | {valid: false; error: string} {
  if (value === undefined) return {valid: true};
  if (typeof value !== 'object' || value === null || Array.isArray(value)) {
    return {valid: false, error: 'list_sessions before must be a cursor object'};
  }

  const cursor = value as Record<string, unknown>;
  if (!isValidSessionId(cursor.sessionId)) {
    return {valid: false, error: 'list_sessions before.sessionId must be 1-128 characters'};
  }
  if (!isValidCursorDate(cursor.updatedAt)) {
    return {valid: false, error: 'list_sessions before.updatedAt must be a valid date'};
  }
  return {valid: true, before: {sessionId: cursor.sessionId, updatedAt: cursor.updatedAt}};
}

